import type { ApiKeyScope } from '@n8n/permissions';
export type UnixTimestamp = number | null;
export type ApiKeyOwner = {
    id: string;
    firstName: string | null;
    lastName: string | null;
    email: string;
};
export type ApiKeyOwnerSummary = ApiKeyOwner & {
    keyCount: number;
};
export type ApiKey = {
    id: string;
    label: string;
    apiKey: string;
    createdAt: string;
    updatedAt: string;
    expiresAt: UnixTimestamp | null;
    scopes: ApiKeyScope[];
    lastUsedAt: string | null;
    owner?: ApiKeyOwner;
};
export type ApiKeyWithRawValue = ApiKey & {
    rawApiKey: string;
};
export type ApiKeyOwnership = 'mine' | 'all';
export type ApiKeyList = {
    items: ApiKey[];
    counts: {
        mine: number;
        all: number;
    };
    totals: {
        mine: number;
        all: number;
    };
    owners: ApiKeyOwnerSummary[];
};
export type ApiKeyAudience = 'public-api' | 'mcp-server-api';
